const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ channel: 'msedge', headless: true });
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 } });
  const page = await ctx.newPage();
  const reqs = [];
  page.on('request', r => { if (r.url().includes('/api/') || r.url().includes('/query/')) reqs.push(r.method() + ' ' + r.url()); });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  const target = 'http://localhost:8095/#/page-query/property-query';
  await page.goto(target, { waitUntil: 'networkidle', timeout: 30000 }).catch(e => console.log('goto-err', e.message));
  await page.waitForTimeout(2500);
  const bodyText = await page.evaluate(() => document.body.innerText).catch(() => '');
  console.log('=== API/QUERY REQUESTS ===');
  console.log(reqs.slice(0, 20).join('\n') || '(none)');
  console.log('=== HAS network-fail text? ===', /连接服务器超时|点击屏幕重试/.test(bodyText));
  console.log('=== body snippet ===');
  console.log(bodyText.slice(0, 400));
  console.log('=== console errors ===');
  console.log(errors.slice(0, 10).join('\n') || '(none)');
  await page.screenshot({ path: 'tools/_smoke_pq.png' }).catch(() => {});
  await browser.close();
})();
